 FlowLayoutPanel PageRoot(string heading){body.SuspendLayout();foreach(Control c in body.Controls.Cast<Control>().ToArray()){body.Controls.Remove(c);c.Dispose();}body.AutoScrollPosition=Point.Empty;currentRoot=new FlowLayoutPanel{AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=Padding.Empty,Padding=Padding.Empty,Location=new Point(body.Padding.Left,body.Padding.Top)};body.Controls.Add(currentRoot);currentRoot.Controls.Add(new Label{Text=heading,Font=new Font("Segoe UI",24),ForeColor=Color.FromArgb(29,35,39),AutoSize=true,Margin=new Padding(0,0,0,8)});string subtitle=heading=="Painel"?"Seu catálogo em um só lugar. Organize os produtos e publique na loja.":heading=="Produtos"?"Pesquise, filtre e atualize seu catálogo. Selecione várias linhas para ações em lote.":heading.Contains("produto")?"Edite os dados e escolha quando o produto aparece na loja.":"Administração do catálogo Videira Vinhoteca";currentRoot.Controls.Add(new Label{Text=subtitle,AutoSize=true,ForeColor=Color.DimGray,Margin=new Padding(0,0,0,24)});currentRoot.ControlAdded+=(s,e)=>FitPage();FitPage();body.ResumeLayout();return currentRoot;}
