 static bool Flag(Dictionary<string,object> p,string key){object v;return p.TryGetValue(key,out v)&&v!=null&&Convert.ToBoolean(v);}
 static decimal Amount(Dictionary<string,object> p){object v;return p.TryGetValue("price",out v)&&v!=null?Convert.ToDecimal(v):0m;}
 void ProductsPage(){page="Produtos";var root=PageRoot("Produtos");var tools=Buttons();tools.Controls.Add(ActionButton("Adicionar novo",()=>{Editor(null);return Task.FromResult(0);},true));tools.Controls.Add(ActionButton("Atualizar lista",async()=>{await Reload();ProductsPage();Notify("Catálogo atualizado do site.");}));root.Controls.Add(tools);
 var filters=Buttons();var search=new TextBox{Width=220,Margin=new Padding(0,4,12,10),AccessibleName="Pesquisar produto"};var status=new AdminComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=130,Margin=new Padding(0,4,12,10),AccessibleName="Situação"};status.Items.AddRange(new object[]{"Todos os status","Publicados","Rascunhos","Destaques","Sem foto"});status.SelectedIndex=0;var cat=new AdminComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=165,Margin=new Padding(0,4,12,10),AccessibleName="Categoria"};cat.Items.Add("Todas as categorias");cat.Items.AddRange(categories.Cast<object>().ToArray());cat.SelectedIndex=0;var order=new AdminComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=160,Margin=new Padding(0,4,12,10),AccessibleName="Ordenação"};order.Items.AddRange(new object[]{"Mais recentes","Nome A–Z","Menor preço","Maior preço"});order.SelectedIndex=0;filters.Controls.AddRange(new Control[]{FilterField(search,"Pesquisar produto"),FilterField(status,"Situação"),FilterField(cat,"Categoria"),FilterField(order,"Ordenar por")});root.Controls.Add(filters);
 var total=new Label{AutoSize=true,ForeColor=Color.DimGray,Margin=new Padding(0,0,0,10)};root.Controls.Add(total);var grid=Grid();grid.Height=360;root.Controls.Add(grid);List<Dictionary<string,object>> visible=new List<Dictionary<string,object>>();Action render=()=>{IEnumerable<Dictionary<string,object>> query=products.Where(p=>String.Join(" ",new[]{SiteApi.Read(p,"name"),SiteApi.Read(p,"category"),SiteApi.Read(p,"country"),SiteApi.Read(p,"grape"),SiteApi.Read(p,"winery")}).IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0).Where(p=>cat.SelectedIndex==0||SiteApi.Read(p,"category")==cat.Text).Where(p=>status.SelectedIndex==0||status.SelectedIndex==1&&Flag(p,"active")||status.SelectedIndex==2&&!Flag(p,"active")||status.SelectedIndex==3&&Flag(p,"featured")||status.SelectedIndex==4&&SiteApi.Read(p,"image_url")=="");if(order.SelectedIndex==1)query=query.OrderBy(p=>SiteApi.Read(p,"name"));if(order.SelectedIndex==2)query=query.OrderBy(Amount);if(order.SelectedIndex==3)query=query.OrderByDescending(Amount);visible=query.ToList();grid.DataSource=visible.Select(p=>new CatalogRow{Id=SiteApi.Read(p,"id"),Produto=SiteApi.Read(p,"name"),Categoria=SiteApi.Read(p,"category"),Preço=SiteApi.Read(p,"price")==""?"Sob consulta":"R$ "+Amount(p).ToString("N2"),Situação=Flag(p,"active")?"Publicado":"Rascunho",Destaque=Flag(p,"featured")?"Sim":"—"}).ToList();if(grid.Columns.Contains("Id")){grid.Columns["Id"].Visible=false;grid.Columns["Produto"].FillWeight=230;}total.Text=visible.Count+" de "+products.Count+" produtos • Ctrl ou Shift para selecionar várias linhas";};render();search.TextChanged+=(s,e)=>render();status.SelectedIndexChanged+=(s,e)=>render();cat.SelectedIndexChanged+=(s,e)=>render();order.SelectedIndexChanged+=(s,e)=>render();
 Func<Dictionary<string,object>> selected=()=>{if(grid.CurrentRow==null)throw new Exception("Selecione um produto.");string id=((CatalogRow)grid.CurrentRow.DataBoundItem).Id;return products.First(p=>SiteApi.Read(p,"id")==id);};grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)Editor(selected());};var actions=Buttons();actions.Controls.Add(ActionButton("Editar",()=>{Editor(selected());return Task.FromResult(0);}));actions.Controls.Add(ActionButton("Duplicar",()=>{var copy=new Dictionary<string,object>(selected());copy["id"]="";copy["name"]=SiteApi.Read(copy,"name")+" (cópia)";copy["active"]=false;copy["featured"]=false;Editor(copy);dirty=true;Notify("Cópia preparada como rascunho. Salve para criar o novo produto.");return Task.FromResult(0);}));var operation=new AdminComboBox{Width=175,DropDownStyle=ComboBoxStyle.DropDownList,Margin=new Padding(8,3,8,8)};operation.Items.AddRange(new object[]{"Publicar selecionados","Mover para rascunho","Marcar destaque","Remover destaque"});operation.SelectedIndex=0;actions.Controls.Add(operation);actions.Controls.Add(ActionButton("Aplicar",async()=>{var ids=grid.SelectedRows.Cast<DataGridViewRow>().Select(r=>((CatalogRow)r.DataBoundItem).Id).ToArray();if(ids.Length==0)throw new Exception("Selecione ao menos um produto.");if(MessageBox.Show(this,"Aplicar ‘"+operation.Text+"’ a "+ids.Length+" produtos no site?","Ação em lote",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;var update=new Dictionary<string,object>();update[operation.SelectedIndex<2?"active":"featured"]=operation.SelectedIndex==0||operation.SelectedIndex==2;await api.UpdateProducts(ids,update);await Reload();ProductsPage();Notify(ids.Length+" produtos atualizados no site.");}));actions.Controls.Add(ActionButton("Exportar CSV",()=>{Export(visible);return Task.FromResult(0);}));root.Controls.Add(actions);dirty=false;}
 void Export(List<Dictionary<string,object>> rows){using(var dialog=new SaveFileDialog{Filter="Catálogo CSV|*.csv",FileName="Videira-Catalogo-"+DateTime.Now.ToString("yyyy-MM-dd")+".csv"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;File.WriteAllText(dialog.FileName,CatalogCsv(rows),new UTF8Encoding(true));Notify(rows.Count+" produtos exportados. A exportação usa os filtros da lista.");}}
 public static string CatalogCsv(List<Dictionary<string,object>> rows){var csv=new StringBuilder("Nome;Categoria;Preço;País;Uva;Produtor;Descrição;Imagem;Publicado;Destaque\r\n");foreach(var p in rows){var values=new[]{SiteApi.Read(p,"name"),SiteApi.Read(p,"category"),SiteApi.Read(p,"price")==""?"":Amount(p).ToString("0.00",CultureInfo.GetCultureInfo("pt-BR")),SiteApi.Read(p,"country"),SiteApi.Read(p,"grape"),SiteApi.Read(p,"winery"),SiteApi.Read(p,"description"),SiteApi.Read(p,"image_url"),Flag(p,"active")?"Sim":"Não",Flag(p,"featured")?"Sim":"Não"};csv.AppendLine(String.Join(";",values.Select(v=>"\""+((v.Length>0&&"=+-@".Contains(v.TrimStart().FirstOrDefault()))?"'":"")+v.Replace("\"","\"\"")+"\"")));}return csv.ToString();}
